import json

def lines_and_blocks(g):
    H,W=len(g),len(g[0])
    def is_v(c):
        return all(g[i][c] in (2,3) and (g[i][c]==2 or g[i-1][c]==3 or i==0) or g[i][c]==2 for i in range(H)) and all(g[i][c]==2 or (g[i][c]==3) for i in range(H))
    # simpler: a line is a row/col where every cell is 2, except cells belonging to block 3s
    hlines=[i for i in range(H) if all(g[i][j]==2 or g[i][j]==3 for j in range(W))]
    vlines=[j for j in range(W) if all(g[i][j]==2 or g[i][j]==3 for i in range(H))]
    centers=[(r,c) for r in range(1,H-1) for c in range(1,W-1)
             if g[r][c]==2 and all(g[i][j]==3 for i in range(r-1,r+2) for j in range(c-1,c+2) if (i,j)!=(r,c))]
    return hlines,vlines,centers

def transform(g):
    H,W=len(g),len(g[0])
    out=[r[:] for r in g]
    hlines,vlines,centers=lines_and_blocks(g)
    for (r,c) in centers:
        onv = c in vlines
        onh = r in hlines
        if onv:      perp, own = ('row', r), ('col', c)
        elif onh:    perp, own = ('col', c), ('row', r)
        else: continue
        # fill perpendicular line: 0 -> 1
        if perp[0]=='row':
            j=perp[1]
            for i in range(H):
                if out[i][j]==0: out[i][j]=1
            crossings=[(r,k) for k in vlines if k!=c]
        else:
            i=perp[1]
            for j in range(W):
                if out[i][j]==0: out[i][j]=1
            crossings=[(k,c) for k in hlines if k!=r]
        for (cr,cc) in crossings:
            if (cr,cc) in centers: continue
            for i in range(cr-1,cr+2):
                for j in range(cc-1,cc+2):
                    if (i,j)==(cr,cc): continue
                    out[i][j]=1
    return out

